// PayPal client for Ringside: sandbox only, server only.
// Hard rules: every POST carries a PayPal-Request-Id the caller generated and stored first (so a retry or a Render
// Workflows replay returns PayPal's original response instead of a second charge); money is integer cents until it
// is formatted for PayPal; the agent never calls capture or refund (only owner-confirmed routes and the close-out do).
//
// Orders v2 and Payments v2 go through PayPal's server SDK (@paypal/paypal-server-sdk, generated by APIMatic).
// Invoicing and webhook verification, which the SDK does not cover, use paypalRequest below. Both share one OAuth token.

import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  ItemCategory,
  OrdersController,
  PaymentsController,
  PaypalExperienceUserAction,
  PaypalWalletContextShippingPreference,
} from "@paypal/paypal-server-sdk";
import type { ApiResponse, Money, OAuthToken, OrderRequest, Order as SdkOrder } from "@paypal/paypal-server-sdk";
import { type Cents, fromPayPalValue, toPayPalValue } from "./money";

const BASE = "https://api-m.sandbox.paypal.com";
export const BRAND_NAME = "Mike's Plumbing";
/** Every Orders and Payments call asks for the full resource, as the raw client always did. */
const PREFER = "return=representation";

export class PayPalError extends Error {
  override name = "PayPalError";
  constructor(
    message: string,
    readonly status: number,
    readonly issue: string | undefined,
    readonly debugId: string | undefined,
  ) {
    super(message);
  }
}

export interface PayPalResponse<T> {
  status: number;
  body: T;
  debugId: string | undefined;
}

type Fetch = typeof fetch;
let fetchImpl: Fetch = (...args) => fetch(...args);
let fetchOverride: Fetch | undefined;

/**
 * Tests swap in a fake fetch that serves recorded sandbox responses. It serves the raw client and, through an axios
 * adapter on the SDK client (the SDK's documented test seam, `unstable_httpClientOptions`), the SDK calls too.
 */
export function setFetchForTests(f: Fetch): void {
  fetchImpl = f;
  fetchOverride = f;
  token = undefined;
  tokenExpiresAt = 0;
  sdkClient = undefined;
}

let token: string | undefined;
let tokenExpiresAt = 0;

async function accessToken(): Promise<string> {
  if (token && Date.now() < tokenExpiresAt - 60_000) return token;
  if (process.env.PAYPAL_ENV !== "sandbox") throw new Error("PAYPAL_ENV must be sandbox");
  const id = process.env.PAYPAL_CLIENT_ID;
  const secret = process.env.PAYPAL_CLIENT_SECRET;
  if (!id || !secret) throw new Error("PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET are not set");
  const res = await fetchImpl(`${BASE}/v1/oauth2/token`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${Buffer.from(`${id}:${secret}`).toString("base64")}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: "grant_type=client_credentials",
  });
  const body = (await res.json().catch(() => ({}))) as { access_token?: string; expires_in?: number; error?: string };
  if (!res.ok || !body.access_token) throw new PayPalError(`Token request failed (${body.error ?? res.status})`, res.status, body.error, undefined);
  token = body.access_token;
  tokenExpiresAt = Date.now() + (body.expires_in ?? 300) * 1000;
  return token;
}

/** One PayPal REST call. A POST must name its PayPal-Request-Id; there is no default, on purpose. */
export async function paypalRequest<T>(
  method: "GET" | "POST" | "PATCH",
  path: string,
  opts: { body?: unknown; requestId?: string } = {},
): Promise<PayPalResponse<T>> {
  if (method === "POST" && !opts.requestId) throw new Error(`POST ${path} needs a PayPal-Request-Id`);
  const headers: Record<string, string> = {
    Authorization: `Bearer ${await accessToken()}`,
    "Content-Type": "application/json",
    Prefer: PREFER,
  };
  if (opts.requestId) headers["PayPal-Request-Id"] = opts.requestId;
  const res = await fetchImpl(`${BASE}${path}`, {
    method,
    headers,
    body: opts.body === undefined ? undefined : JSON.stringify(opts.body),
  });
  const body = (await res.json().catch(() => ({}))) as T & { details?: { issue?: string }[]; name?: string; message?: string; debug_id?: string };
  const debugId = res.headers.get("paypal-debug-id") ?? body.debug_id;
  if (!res.ok) {
    const issue = body.details?.[0]?.issue ?? body.name;
    throw new PayPalError(`${method} ${path} failed: ${issue ?? res.status}`, res.status, issue, debugId);
  }
  return { status: res.status, body, debugId };
}

// --- The server SDK --------------------------------------------------------------------------------------------

let sdkClient: Client | undefined;

/**
 * The SDK client, built once: Sandbox environment (never Production), a 30 s timeout per attempt (the SDK default is
 * none), and no SDK retries (the caller and Render Workflows retry, replaying the same request ID). It takes its OAuth
 * token from accessToken() through oAuthTokenProvider, so the SDK and the raw client share one token.
 */
function sdk(): Client {
  sdkClient ??= new Client({
    environment: Environment.Sandbox,
    timeout: 30_000,
    httpClientOptions: { retryConfig: { maxNumberOfRetries: 0 } },
    clientCredentialsAuthCredentials: {
      oAuthClientId: process.env.PAYPAL_CLIENT_ID ?? "",
      oAuthClientSecret: process.env.PAYPAL_CLIENT_SECRET ?? "",
      // Must never reject: the SDK caches a rejected token for good. sdkCall has already fetched the token, so this
      // only reads the cache; on a failure it hands back an expired token and is asked again on the next call.
      oAuthTokenProvider: async (): Promise<OAuthToken> => {
        try {
          const accessTokenValue = await accessToken();
          return { accessToken: accessTokenValue, tokenType: "Bearer", expiry: BigInt(Math.floor((tokenExpiresAt - 60_000) / 1000)) };
        } catch {
          return { accessToken: "", tokenType: "Bearer", expiry: BigInt(0) };
        }
      },
    },
    ...(fetchOverride ? { unstable_httpClientOptions: { adapter: fetchAdapter(fetchOverride) } } : {}),
  });
  return sdkClient;
}

/** Runs one SDK call: sandbox and credentials checked first, PayPal's error body mapped onto PayPalError. */
async function sdkCall<T>(run: (client: Client) => Promise<ApiResponse<T>>): Promise<T> {
  await accessToken();
  try {
    return (await run(sdk())).result;
  } catch (error) {
    if (error instanceof ApiError) throw toPayPalError(error);
    throw error;
  }
}

/** A POST through the SDK must name its PayPal-Request-Id, as in paypalRequest. */
function requireRequestId(requestId: string, what: string): string {
  if (!requestId) throw new Error(`POST ${what} needs a PayPal-Request-Id`);
  return requestId;
}

interface PayPalErrorBody {
  name?: string;
  debug_id?: string;
  details?: { issue?: string }[];
}

/** The SDK's ApiError carries PayPal's error body with its wire field names (`debug_id`, `details[].issue`). */
function toPayPalError(error: ApiError): PayPalError {
  let body = error.result as PayPalErrorBody | undefined;
  if (!body && typeof error.body === "string") {
    try {
      body = JSON.parse(error.body) as PayPalErrorBody;
    } catch {
      body = undefined;
    }
  }
  const issue = body?.details?.[0]?.issue ?? body?.name;
  const debugId = error.headers?.["paypal-debug-id"] ?? body?.debug_id;
  const path = error.request?.url ? new URL(error.request.url).pathname : "";
  return new PayPalError(`${error.request?.method ?? ""} ${path} failed: ${issue ?? error.statusCode}`, error.statusCode, issue, debugId);
}

/** The slice of an axios request config the test adapter reads. */
interface AxiosRequest {
  url?: string;
  method?: string;
  data?: unknown;
  headers?: { toJSON?: () => Record<string, unknown> } & Record<string, unknown>;
}

/** An axios adapter that sends the SDK's requests through the test fetch and hands back the raw body as text. */
function fetchAdapter(f: Fetch) {
  return async (config: AxiosRequest) => {
    const raw = typeof config.headers?.toJSON === "function" ? config.headers.toJSON() : (config.headers ?? {});
    const headers = Object.fromEntries(
      Object.entries(raw)
        .filter(([, v]) => v !== undefined && v !== null && typeof v !== "function")
        .map(([k, v]) => [k, String(v)]),
    );
    const res = await f(String(config.url), {
      method: (config.method ?? "get").toUpperCase(),
      headers,
      body: typeof config.data === "string" ? config.data : undefined,
    });
    return { data: await res.text(), status: res.status, statusText: res.statusText, headers: Object.fromEntries(res.headers), config, request: {} };
  };
}

const usd = (cents: Cents): Money => ({ currencyCode: "USD", value: toPayPalValue(cents) });

function amountValue(money: Money | undefined, what: string): string {
  if (!money?.value) throw new Error(`PayPal returned ${what} without an amount`);
  return money.value;
}

// --- Orders --------------------------------------------------------------------------------------------------

interface Link {
  href: string;
  rel: string;
}
export interface Order {
  id: string;
  status: string;
  intent: "AUTHORIZE" | "CAPTURE";
  links?: Link[];
  /** Read only to address the receipt; never stored (privacy rule). Guest card payers may have no email. */
  payer?: { email_address?: string };
  payment_source?: { paypal?: { email_address?: string } };
  purchase_units?: {
    payments?: {
      authorizations?: { id: string; status: string; expiration_time?: string; amount: { value: string } }[];
      captures?: { id: string; status: string; amount: { value: string } }[];
    };
  }[];
}

/** The SDK's order model, in the wire shape the rest of the app reads (only the fields it uses). */
function toOrder(order: SdkOrder): Order {
  return {
    id: order.id ?? "",
    status: order.status ?? "",
    intent: order.intent === CheckoutPaymentIntent.Capture ? "CAPTURE" : "AUTHORIZE",
    links: order.links?.map(({ href, rel }) => ({ href, rel })),
    payer: order.payer && { email_address: order.payer.emailAddress },
    payment_source: order.paymentSource && { paypal: order.paymentSource.paypal && { email_address: order.paymentSource.paypal.emailAddress } },
    purchase_units: order.purchaseUnits?.map((unit) => ({
      payments: unit.payments && {
        authorizations: unit.payments.authorizations?.map((a) => ({
          id: a.id ?? "",
          status: a.status ?? "",
          expiration_time: a.expirationTime,
          amount: { value: amountValue(a.amount, `authorization ${a.id}`) },
        })),
        captures: unit.payments.captures?.map((c) => ({
          id: c.id ?? "",
          status: c.status ?? "",
          amount: { value: amountValue(c.amount, `capture ${c.id}`) },
        })),
      },
    })),
  };
}

/** One line on a PayPal order: always priced from the price book or the add-on card, never by the model. */
export interface OrderItem {
  name: string;
  qty: number;
  unitPriceCents: Cents;
  totalCents: Cents;
}

export interface OrderInput {
  intent: "AUTHORIZE" | "CAPTURE";
  items: readonly OrderItem[];
  totalCents: Cents;
  jobCode: string;
  description: string;
  requestId: string;
  returnUrl: string;
  cancelUrl: string;
}

/** Creates an order whose items and total come from the rate card; the payer approves it on PayPal. */
export async function createOrder(input: OrderInput): Promise<Order> {
  const itemTotal = input.items.reduce((sum, item) => sum + item.totalCents, 0);
  if (itemTotal !== input.totalCents) throw new Error(`Items add up to ${itemTotal}, not ${input.totalCents}`);
  const body: OrderRequest = {
    intent: input.intent === "CAPTURE" ? CheckoutPaymentIntent.Capture : CheckoutPaymentIntent.Authorize,
    purchaseUnits: [
      {
        referenceId: input.jobCode,
        customId: input.jobCode,
        description: input.description.slice(0, 127),
        amount: { ...usd(input.totalCents), breakdown: { itemTotal: usd(itemTotal) } },
        items: input.items.map((item) => ({
          name: item.name,
          quantity: String(item.qty),
          unitAmount: usd(item.unitPriceCents),
          category: ItemCategory.DigitalGoods,
        })),
      },
    ],
    paymentSource: {
      paypal: {
        experienceContext: {
          brandName: BRAND_NAME,
          shippingPreference: PaypalWalletContextShippingPreference.NoShipping,
          userAction: input.intent === "CAPTURE" ? PaypalExperienceUserAction.PayNow : PaypalExperienceUserAction.Continue,
          returnUrl: input.returnUrl,
          cancelUrl: input.cancelUrl,
        },
      },
    },
  };
  const paypalRequestId = requireRequestId(input.requestId, "/v2/checkout/orders");
  return toOrder(await sdkCall((c) => new OrdersController(c).createOrder({ body, paypalRequestId, prefer: PREFER })));
}

export function approvalUrl(order: Order): string | undefined {
  return order.links?.find((l) => l.rel === "payer-action" || l.rel === "approve")?.href;
}

export async function getOrder(orderId: string): Promise<Order> {
  return toOrder(await sdkCall((c) => new OrdersController(c).getOrder({ id: orderId })));
}

/** After the payer approves an AUTHORIZE order: places the hold and returns its authorization. */
export async function authorizeOrder(orderId: string, requestId: string) {
  const paypalRequestId = requireRequestId(requestId, `/v2/checkout/orders/${orderId}/authorize`);
  const order = await sdkCall((c) => new OrdersController(c).authorizeOrder({ id: orderId, paypalRequestId, prefer: PREFER }));
  const auth = order.purchaseUnits?.[0]?.payments?.authorizations?.[0];
  if (!auth?.id) throw new Error(`Order ${orderId} authorized without an authorization`);
  return {
    authorizationId: auth.id,
    status: auth.status ?? "",
    amountCents: fromPayPalValue(amountValue(auth.amount, `authorization ${auth.id}`)),
    expiresAt: auth.expirationTime,
  };
}

/** After the payer approves a CAPTURE order (the change order's second payment): takes the money. */
export async function captureOrder(orderId: string, requestId: string) {
  const paypalRequestId = requireRequestId(requestId, `/v2/checkout/orders/${orderId}/capture`);
  const order = await sdkCall((c) => new OrdersController(c).captureOrder({ id: orderId, paypalRequestId, prefer: PREFER }));
  const capture = order.purchaseUnits?.[0]?.payments?.captures?.[0];
  if (!capture?.id) throw new Error(`Order ${orderId} captured without a capture`);
  return { captureId: capture.id, status: capture.status ?? "", amountCents: fromPayPalValue(amountValue(capture.amount, `capture ${capture.id}`)) };
}

// --- Authorizations ------------------------------------------------------------------------------------------

/**
 * Captures a hold. Only the owner's confirmed "job done" (through the close-out flow) may call this. PayPal caps a
 * capture at 115% of the hold (sandbox gate, 2026-11-05); a replay with the same request ID returns the same capture.
 */
export async function captureAuthorization(input: { authorizationId: string; amountCents: Cents; finalCapture: boolean; requestId: string; invoiceId: string }) {
  const paypalRequestId = requireRequestId(input.requestId, `/v2/payments/authorizations/${input.authorizationId}/capture`);
  const capture = await sdkCall((c) =>
    new PaymentsController(c).captureAuthorizedPayment({
      authorizationId: input.authorizationId,
      paypalRequestId,
      prefer: PREFER,
      body: { amount: usd(input.amountCents), finalCapture: input.finalCapture, invoiceId: input.invoiceId },
    }),
  );
  if (!capture.id) throw new Error(`Authorization ${input.authorizationId} captured without a capture ID`);
  return { captureId: capture.id, status: capture.status ?? "", amountCents: fromPayPalValue(amountValue(capture.amount, `capture ${capture.id}`)) };
}

export async function voidAuthorization(authorizationId: string, requestId: string) {
  const paypalRequestId = requireRequestId(requestId, `/v2/payments/authorizations/${authorizationId}/void`);
  await sdkCall((c) => new PaymentsController(c).voidPayment({ authorizationId, paypalRequestId, prefer: PREFER }));
}

// --- Webhooks ------------------------------------------------------------------------------------------------

/** Asks PayPal whether a webhook delivery is genuine. Returns false on any failure. */
export async function verifyWebhook(headers: Headers, rawBody: string): Promise<boolean> {
  const webhookId = process.env.PAYPAL_WEBHOOK_ID;
  if (!webhookId) return false;
  const get = (name: string) => headers.get(name) ?? "";
  try {
    const { body } = await paypalRequest<{ verification_status?: string }>("POST", "/v1/notifications/verify-webhook-signature", {
      requestId: `verify-${get("paypal-transmission-id")}`,
      body: {
        auth_algo: get("paypal-auth-algo"),
        cert_url: get("paypal-cert-url"),
        transmission_id: get("paypal-transmission-id"),
        transmission_sig: get("paypal-transmission-sig"),
        transmission_time: get("paypal-transmission-time"),
        webhook_id: webhookId,
        webhook_event: JSON.parse(rawBody),
      },
    });
    return body.verification_status === "SUCCESS";
  } catch {
    return false;
  }
}

// --- Invoicing (the customer's receipt) ----------------------------------------------------------------------
// Sandbox gate 2026-11-05 (scripts/sandbox/receipt-invoice.mjs): Invoicing ignores PayPal-Request-Id. A create replay
// fails with DUPLICATE_INVOICE_NUMBER and a record-payment replay records a second payment. We still send a stored
// request ID on every POST (hard rule); receipts.ts makes the flow idempotent from the invoice's own state instead.

/** The business on every receipt: Mike's Plumbing is fictional, so no street address. */
export const INVOICER = {
  business_name: BRAND_NAME,
  address: { admin_area_2: "Saginaw", admin_area_1: "MI", country_code: "US" },
} as const;

export interface Invoice {
  id: string;
  status: string;
  detail?: {
    invoice_number?: string;
    reference?: string;
    metadata?: { recipient_view_url?: string; invoicer_view_url?: string };
  };
  primary_recipients?: { billing_info?: { email_address?: string } }[];
  amount?: { value: string };
  payments?: {
    paid_amount?: { value: string };
    transactions?: { payment_id?: string; type?: string; method?: string; note?: string; amount?: { value: string } }[];
  };
}

export interface InvoiceLine {
  name: string;
  description?: string;
  amountCents: Cents;
}

export interface InvoiceInput {
  invoiceNumber: string;
  reference: string;
  note: string;
  lines: readonly InvoiceLine[];
  recipient: { name?: string; email?: string };
  website?: string;
  requestId: string;
}

function personName(full: string): { given_name: string; surname?: string } {
  const parts = full.trim().split(/\s+/);
  const surname = parts.length > 1 ? parts.pop() : undefined;
  return { given_name: parts.join(" ").slice(0, 140), ...(surname ? { surname: surname.slice(0, 140) } : {}) };
}

/** Creates a draft invoice. Each line is one unit at its exact cents; totals are never computed in floats. */
export async function createInvoice(input: InvoiceInput): Promise<Invoice> {
  const billing = {
    ...(input.recipient.name ? { name: personName(input.recipient.name) } : {}),
    ...(input.recipient.email ? { email_address: input.recipient.email } : {}),
  };
  const { body } = await paypalRequest<Invoice>("POST", "/v2/invoicing/invoices", {
    requestId: input.requestId,
    body: {
      detail: {
        invoice_number: input.invoiceNumber,
        reference: input.reference.slice(0, 120),
        currency_code: "USD",
        note: input.note.slice(0, 4000),
        payment_term: { term_type: "DUE_ON_RECEIPT" },
      },
      invoicer: { ...INVOICER, ...(input.website ? { website: input.website } : {}) },
      ...(Object.keys(billing).length ? { primary_recipients: [{ billing_info: billing }] } : {}),
      items: input.lines.map((line) => ({
        name: line.name.slice(0, 200),
        ...(line.description ? { description: line.description.slice(0, 1000) } : {}),
        quantity: "1",
        unit_amount: { currency_code: "USD", value: toPayPalValue(line.amountCents) },
      })),
    },
  });
  return body;
}

export async function getInvoice(invoiceId: string): Promise<Invoice> {
  return (await paypalRequest<Invoice>("GET", `/v2/invoicing/invoices/${encodeURIComponent(invoiceId)}`)).body;
}

/** Finds an invoice by its exact number (after DUPLICATE_INVOICE_NUMBER: an earlier attempt created it). */
export async function findInvoiceByNumber(invoiceNumber: string, requestId: string): Promise<Invoice | undefined> {
  const { body } = await paypalRequest<{ items?: Invoice[] }>("POST", "/v2/invoicing/search-invoices?page_size=10", {
    requestId,
    body: { invoice_number: invoiceNumber },
  });
  return body.items?.find((inv) => inv.detail?.invoice_number === invoiceNumber);
}

/** Issues a draft. With sendToRecipient false PayPal sends no email and the invoice works as a share link. */
export async function sendInvoice(invoiceId: string, opts: { sendToRecipient: boolean; requestId: string }): Promise<void> {
  await paypalRequest<unknown>("POST", `/v2/invoicing/invoices/${encodeURIComponent(invoiceId)}/send`, {
    requestId: opts.requestId,
    body: { send_to_recipient: opts.sendToRecipient, send_to_invoicer: false },
  });
}

/**
 * Records money already taken through PayPal against the invoice. The type is EXTERNAL with method PAYPAL: a PAYPAL-type
 * record wants a payment made on the invoice itself and returns RESOURCE_NOT_FOUND for an order's capture (sandbox gate).
 */
export async function recordInvoicePayment(invoiceId: string, opts: { amountCents: Cents; note: string; requestId: string }): Promise<string | undefined> {
  const { body } = await paypalRequest<{ payment_id?: string }>("POST", `/v2/invoicing/invoices/${encodeURIComponent(invoiceId)}/payments`, {
    requestId: opts.requestId,
    body: { type: "EXTERNAL", method: "PAYPAL", note: opts.note, amount: { currency_code: "USD", value: toPayPalValue(opts.amountCents) } },
  });
  return body.payment_id;
}

/** The payer's email on an approved order, if PayPal has one. Use it at once; never store it. */
export function payerEmail(order: Order): string | undefined {
  return order.payer?.email_address ?? order.payment_source?.paypal?.email_address ?? undefined;
}
